/**
 * The flat bodies a bot can wear: Seira, the shipped mascot, her cast, and the festival bodies.
 *
 * GENERATED FILE — do not hand-edit. Run `pnpm gen:carved` to rebuild it from
 * `scripts/gen-carved-bodies.ts`.
 *
 * Drawn flat: the bot's own colour (or a pale or fixed stand-in), a few fixed-colour accents
 * and a carved face. Paths are in a 240-unit square centred on x = 120.
 */

/** Every Brand body id, in the order the picker shows them. */
export const BRAND_BODY_IDS = ["seira", "mira", "lumi", "rhea", "kiri", "iris", "vera", "pippa", "maren", "corvin", "felix", "silas", "flint", "bix", "theo", "rocco", "milo", "leo", "aldo", "orin", "rico", "rook", "ronan", "bruno", "ansel", "ellis"] as const;

export type BrandBodyId = (typeof BRAND_BODY_IDS)[number];

/** Every Halloween body id, in the order the picker shows them. */
export const HALLOWEEN_BODY_IDS = ["pumpkin", "ghost", "witch", "bat", "cat", "skull", "monster", "mummy", "vampire", "spider"] as const;

export type HalloweenBodyId = (typeof HALLOWEEN_BODY_IDS)[number];

/** Every Diwali body id, in the order the picker shows them. */
export const DIWALI_BODY_IDS = ["rocket", "anaar", "chakri", "sparkler", "bomb", "laddu", "chakli", "jalebi", "katli", "karanji"] as const;

export type DiwaliBodyId = (typeof DIWALI_BODY_IDS)[number];

export const CARVED_BODY_IDS = [...BRAND_BODY_IDS, ...HALLOWEEN_BODY_IDS, ...DIWALI_BODY_IDS] as const;

export type CarvedBodyId = (typeof CARVED_BODY_IDS)[number];

export interface CarvedEyes {
  /** Rest position of the pair's centre. */
  cx: number;
  cy: number;
  /** Half the distance between the two eyes. */
  dx: number;
  /** Resting pill size. */
  w: number;
  h: number;
  /** Diameter when startled. */
  round: number;
  ink: string;
  /** False when the drawing carries its own mouth. */
  mouth: boolean;
  mouthInk: string;
  /** Where the smile sits when it can't hang under the eyes. */
  mouthY: number | null;
}

export interface CarvedBody {
  id: CarvedBodyId;
  /** Human-readable name, used for the picker and the accessible label. */
  name: string;
  /** "bot" fills with the bot's colour, "pale" with a near-white tint of it, "bone" with `bone`,
   * "hair" with the bot's colour, or `bone` for silver and chrome. */
  paint: "bot" | "pale" | "bone" | "hair";
  bone: string | null;
  eyes: CarvedEyes;
  /** Where the eyes may show. */
  clip: string;
  /** Draw order, bottom first. "body" is the paint; "accent" is the bot's colour. */
  parts: ReadonlyArray<{ fill: string; d: string }>;
}

